-- Schema for users
CREATE TABLE users (
      id TEXT PRIMARY KEY,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      salt TEXT NOT NULL,
      name TEXT NOT NULL,
      role TEXT DEFAULT 'admin',
      created_at TEXT NOT NULL
    , login_id TEXT, recovery_email TEXT, recovery_phone TEXT, is_active INTEGER DEFAULT 1, failed_login_attempts INTEGER DEFAULT 0, locked_until TEXT, updated_at TEXT, last_login_at TEXT, password_changed_at TEXT, security_question TEXT, security_answer_hash TEXT, failed_recovery_attempts INTEGER DEFAULT 0, recovery_locked_until TEXT);


-- Schema for chits
CREATE TABLE chits (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      chit_value REAL NOT NULL,
      total_months INTEGER NOT NULL,
      total_members INTEGER NOT NULL,
      start_month TEXT NOT NULL,
      end_month TEXT NOT NULL,
      status TEXT DEFAULT 'active',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    , current_month INTEGER DEFAULT 1, monthly_chit_value REAL DEFAULT 301500);


-- Schema for chit_month_rules
CREATE TABLE chit_month_rules (
      id TEXT PRIMARY KEY,
      chit_id TEXT NOT NULL,
      month_number INTEGER NOT NULL,
      month_name TEXT NOT NULL,
      pre_lift_payment REAL NOT NULL,
      post_lift_payment REAL NOT NULL,
      monthly_chit_value REAL NOT NULL,
      expected_lift_payout REAL NOT NULL,
      FOREIGN KEY (chit_id) REFERENCES chits(id) ON DELETE CASCADE,
      UNIQUE(chit_id, month_number)
    );


-- Schema for members
CREATE TABLE members (
      id TEXT PRIMARY KEY,
      chit_id TEXT NOT NULL,
      customer_name TEXT NOT NULL,
      phone TEXT NOT NULL,
      ticket_number TEXT,
      status TEXT DEFAULT 'active',
      join_date TEXT NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (chit_id) REFERENCES chits(id) ON DELETE CASCADE
    );


-- Schema for lift_details
CREATE TABLE lift_details (
      id TEXT PRIMARY KEY,
      chit_id TEXT NOT NULL,
      member_id TEXT NOT NULL UNIQUE,
      lift_month INTEGER NOT NULL,
      lift_amount_received REAL NOT NULL,
      lift_date TEXT NOT NULL,
      notes TEXT,
      created_at TEXT NOT NULL, status TEXT DEFAULT 'Completed', payment_method TEXT DEFAULT 'Cash', reference_number TEXT, updated_at TEXT,
      FOREIGN KEY (chit_id) REFERENCES chits(id) ON DELETE CASCADE,
      FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE
    );


-- Schema for monthly_dues
CREATE TABLE monthly_dues (
      id TEXT PRIMARY KEY,
      chit_id TEXT NOT NULL,
      member_id TEXT NOT NULL,
      month_number INTEGER NOT NULL,
      month_name TEXT NOT NULL,
      due_amount REAL NOT NULL,
      paid_amount REAL NOT NULL DEFAULT 0,
      balance_amount REAL NOT NULL,
      status TEXT NOT NULL DEFAULT 'PENDING',
      due_date TEXT NOT NULL,
      generated_at TEXT NOT NULL,
      FOREIGN KEY (chit_id) REFERENCES chits(id) ON DELETE CASCADE,
      FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE,
      UNIQUE(chit_id, member_id, month_number)
    );


-- Schema for payments
CREATE TABLE payments (
      id TEXT PRIMARY KEY,
      monthly_due_id TEXT NOT NULL,
      chit_id TEXT NOT NULL,
      member_id TEXT NOT NULL,
      month_number INTEGER NOT NULL,
      month_name TEXT NOT NULL,
      amount REAL NOT NULL,
      payment_method TEXT NOT NULL,
      reference_no TEXT,
      notes TEXT,
      payment_date TEXT NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (monthly_due_id) REFERENCES monthly_dues(id) ON DELETE CASCADE,
      FOREIGN KEY (chit_id) REFERENCES chits(id) ON DELETE CASCADE,
      FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE
    );


-- Schema for sessions
CREATE TABLE sessions (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      session_token_hash TEXT UNIQUE NOT NULL,
      expires_at TEXT NOT NULL,
      created_at TEXT NOT NULL,
      last_used_at TEXT NOT NULL,
      ip_address TEXT,
      user_agent TEXT,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );


-- Schema for password_resets
CREATE TABLE password_resets (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      recovery_code TEXT NOT NULL,
      reset_token TEXT UNIQUE NOT NULL,
      expires_at TEXT NOT NULL,
      used INTEGER DEFAULT 0,
      created_at TEXT NOT NULL,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );


